// Sound: analog level on AOUT, threshold output on DOUT.
const int ANALOG_PIN = {{AOUT}};
const int DIGITAL_PIN = {{DOUT}};

void setup() {
  Serial.begin(115200);
  pinMode(DIGITAL_PIN, INPUT);
}

void loop() {
  int level = analogRead(ANALOG_PIN);
  bool triggered = digitalRead(DIGITAL_PIN) == LOW;
  Serial.print("Sound level: ");
  Serial.print(level);
  Serial.println(triggered ? "  (threshold reached)" : "");
  delay(500);
}
